        [Str.NavHelp] = "Ajutor",
        [Str.HelpTitle] = "Ajutor",
        [Str.HelpStartH] = "Primii pași",
        [Str.HelpStartBody] = "Deschide Conectare și introdu ID-ul sincronizării și parola pentru a conecta acest dispozitiv. Marcajele sunt criptate pe dispozitiv înainte de a fi încărcate, așa că serverul nu le vede niciodată în clar. O parolă uitată nu poate fi recuperată: păstreaz-o în siguranță.",
        [Str.HelpAddH] = "Adăugarea marcajelor",
        [Str.HelpAddBody] = "Apasă Adaugă pentru a crea un marcaj sau un folder. Poți partaja o pagină din browser sau din altă aplicație către Keepmark pentru a o salva.",
        [Str.HelpSyncH] = "Sincronizare",
        [Str.HelpSyncBody] = "În modul Automat fiecare modificare este sincronizată imediat; în modul Manual doar când apeși Sincronizează acum. Dacă atât acest dispozitiv, cât și serverul s-au schimbat, alegi ce păstrezi: copia de pe server, marcajele tale locale sau ambele îmbinate. Nimic nu este suprascris fără o copie de siguranță mai întâi.",
        [Str.HelpBackupH] = "Copii de rezervă și anulare",
        [Str.HelpBackupBody] = "Înainte de un pas distructiv (descărcare, încărcare, import, restaurare, schimbare de parolă sau curățare de duplicate) aplicația salvează o copie de siguranță. Le găsești în Copii de rezervă, la Copii de siguranță, și poți restaura una pentru a anula modificarea. Mutarea sau ștergerea unui marcaj ori a unui folder nu salvează nicio copie: folosește Anulează, afișat câteva secunde. Schimbarea sincronizării nu salvează nicio copie: sincronizarea pe care o părăsești rămâne pe server. În Copii de rezervă poți exporta și un fișier criptat și restaura din el.",
        [Str.HelpToolsH] = "Duplicate și sincronizări",
        [Str.HelpToolsBody] = "Duplicate găsește marcajele cu același URL, ca să poți șterge copiile în plus. Sincronizări listează sincronizările salvate pe acest dispozitiv: activează alta sau adaugă o sincronizare existentă cu ID-ul și parola ei ori cu QR-ul din browser.",
        [Str.HelpLockH] = "Blocarea aplicației",
        [Str.HelpLockBody] = "În Setări, la Blocarea aplicației, poți cere biometrie sau un PIN pentru a deschide Keepmark și poți alege cât timp rămâne deblocată.",
        [Str.HelpOrganizeH] = "Recente, duplicate și foldere",
        [Str.HelpOrganizeBody] = "Acasă poate lista marcajele adăugate ultima dată, împreună cu folderul în care se află (Setări, Arată adăugatele recent). Când adaugi o pagină deja salvată, formularul îți spune unde. În selectorul de foldere, Folder nou creează un folder pe loc. Ștergerea unui folder cu multe marcaje cere mai întâi confirmare.",
